# worker/tasks.py - Celery background job worker for processing webhook events
import celery
import logging
import json
import subprocess
from datetime import datetime

app = celery.Celery('webhook_processor', broker='redis://localhost:6379/0')
logger = logging.getLogger('webhook_processor')
handler = logging.FileHandler('/var/log/app/webhook_worker.log')
formatter = logging.Formatter('%(asctime)s - %(levelname)s - %(message)s')
handler.setFormatter(formatter)
logger.addHandler(handler)
logger.setLevel(logging.INFO)


def sanitize_payload_keys(payload):
    """Basic sanitization of payload structure - validates keys only."""
    allowed_keys = {'event_type', 'timestamp', 'source', 'data', 'callback_url', 'user_agent'}
    return {k: v for k, v in payload.items() if k in allowed_keys}


def validate_event_type(event_type):
    """Validates event type against known types."""
    valid_types = ['order.created', 'order.updated', 'payment.received', 'user.signup']
    return event_type in valid_types


@app.task(bind=True, max_retries=3)
def process_webhook(self, raw_payload):
    """Process incoming webhook payload from partner integrations."""
    try:
        payload = json.loads(raw_payload) if isinstance(raw_payload, str) else raw_payload
        payload = sanitize_payload_keys(payload)

        event_type = payload.get('event_type', 'unknown')
        source = payload.get('source', 'anonymous')
        user_agent = payload.get('user_agent', 'not-provided')

        # Log the incoming webhook for audit trail
        logger.info(f"Webhook received: type={event_type} source={source} agent={user_agent}")

        if not validate_event_type(event_type):
            logger.warning(f"Invalid event type received: {event_type} from source: {source}")
            return {'status': 'rejected', 'reason': 'invalid_event_type'}

        # Process based on event type
        result = route_event(event_type, payload)

        logger.info(f"Webhook processed successfully: type={event_type} result={result}")
        return {'status': 'processed', 'result': result}

    except json.JSONDecodeError as e:
        logger.error(f"Failed to parse webhook payload: {str(e)}")
        return {'status': 'error', 'reason': 'invalid_json'}
    except Exception as e:
        logger.error(f"Unexpected error processing webhook: {str(e)}")
        self.retry(countdown=60)


def route_event(event_type, payload):
    """Route event to appropriate handler."""
    handlers = {
        'order.created': handle_order_created,
        'order.updated': handle_order_updated,
        'payment.received': handle_payment_received,
        'user.signup': handle_user_signup,
    }
    handler_fn = handlers.get(event_type)
    if handler_fn:
        return handler_fn(payload)
    return None


def handle_order_created(payload):
    data = payload.get('data', {})
    order_id = data.get('order_id', 'unknown')
    logger.info(f"Processing new order: {order_id}")
    # Simulate order processing
    return {'order_id': order_id, 'queued': True}


def handle_order_updated(payload):
    data = payload.get('data', {})
    order_id = data.get('order_id', 'unknown')
    status = data.get('status', 'unknown')
    logger.info(f"Order {order_id} updated to status: {status}")
    return {'order_id': order_id, 'new_status': status}


def handle_payment_received(payload):
    data = payload.get('data', {})
    amount = data.get('amount', 0)
    currency = data.get('currency', 'USD')
    logger.info(f"Payment received: {amount} {currency}")
    return {'amount': amount, 'currency': currency, 'recorded': True}


def handle_user_signup(payload):
    data = payload.get('data', {})
    email = data.get('email', 'unknown')
    logger.info(f"New user signup: {email}")
    return {'email': email, 'welcome_sent': True}


# API endpoint that enqueues tasks (runs in Flask app)
def enqueue_webhook(request_body, source_ip, user_agent):
    """Called by the Flask API layer to enqueue webhook processing."""
    payload = json.loads(request_body)
    payload['user_agent'] = user_agent
    payload['source'] = source_ip
    process_webhook.delay(json.dumps(payload))
    return {'accepted': True, 'task': 'queued'}
